mapper.select:
select tda.device_id as deviceId, td.device_no as deviceNo, td.device_name as deviceName, tdd.device_type as deviceType, tdd.device_system as deviceSystem, tdd.device_system_version as deviceSystemVersion, tda.last_app as app, tda.app_time as appTime, td.device_charge as deviceCharge from t_device_app tda inner join t_device td on tda.device_id = td.id inner join t_device_detail tdd on td.id = tdd.device_id
and td.device_no = #{queryDTO.deviceNo}
and tdd.device_type = #{queryDTO.deviceType}
and tda.last_app = #{queryDTO.app}
and tda.del_flag = 'N'
order by tda.app_time desc
